// USDA ERS Food Access Research Atlas 2019, tract data summed to county.
// Generated by scripts/refresh-usda-fara-county.mjs from USDA's own ArcGIS
// service; do not edit the JSON by hand. Every county figure is a sum or
// count of USDA tract values, so it is labeled MODELED.
import fara from "@/data/usda-fara-county.generated.json";

export interface FoodAccessData {
  county: string;
  fips: string;
  /** Tracts in the county in FARA 2019. */
  totalTracts: number;
  /** Tracts USDA flags low access (1 mile urban / 10 miles rural). */
  lowAccessTracts: number;
  lowAccessPct: number;
  /** Low-income, low-access tracts: USDA's food desert tract flag. */
  lilaTracts: number;
  lowAccessPop: number;
  lowIncomeLowAccessPop: number;
  seniorLowAccessPop: number;
  /** Housing units without a vehicle, beyond the low-access distance. */
  noVehicleLowAccessHousingUnits: number;
  source: string;
}

export const FOOD_ACCESS_SOURCE = "USDA ERS Food Access Research Atlas 2019";
export const FOOD_ACCESS_METHOD = fara.provenance.method;

export const MICHIGAN_FOOD_ACCESS: FoodAccessData[] = fara.counties.map((c) => ({
  ...c,
  source: FOOD_ACCESS_SOURCE,
}));

export function getFoodAccessByCounty(county: string): FoodAccessData | null {
  return MICHIGAN_FOOD_ACCESS.find((f) => f.county === county) ?? null;
}
